""" A-E-I-O-U """

def main():
    """A-E-I-O-U"""
    text = str(input().lower())
    vowels = ['a', 'e', 'i', 'o', 'u']
    a = 0
    e = 0
    i = 0
    o = 0
    u = 0
    for char in text:
        if char in vowels:
            if char == 'a':
                a = a + 1
            elif char == 'e':
                e = e + 1
            elif char == 'i':
                i = i + 1
            elif char == 'o':
                o = o + 1
            elif char == 'u':
                u = u + 1
    if a > 0:
        print(f"a : {a}")
    if e > 0:
        print(f"e : {e}")
    if i > 0:
        print(f"i : {i}")
    if o > 0:
        print(f"o : {o}")
    if u > 0:
        print(f"u : {u}")

if __name__ == "__main__":
    main()

""" Basic ATM """

def main():
    """Basic ATM"""
    n = float(input())

    if 100 <= n <= 20000:
        thoundsands = n // 1000
        n = n-thoundsands * 1000
        five_hundred = n // 500
        n = n-five_hundred * 500
        one_hundred = n // 100
        n = n-one_hundred * 100

        if n > 0:
            print("ERROR")
        else:
            if thoundsands > 0:
                print(f"1000 = {thoundsands:.0f}")
            if five_hundred > 0:
                print(f"500 = {five_hundred:.0f}")
            if one_hundred > 0:
                print(f"100 = {one_hundred:.0f}")

    else:
        print("ERROR")

if __name__ == "__main__":
    main()

""" FizzBuzz """


def main():
    """FizzBuzz"""
    n = int(input())

    for i in range(1, n + 1):
        # ต้องเช็กเงื่อนไขที่เจาะจงที่สุด (หารด้วย 15 ลงตัว) ก่อนเสมอ
        if not i % 15:
            print("FizzBuzz")
        elif not i % 3:
            print("Fizz")
        elif not i % 5:
            print("Buzz")
        else:
            print(i)


if __name__ == "__main__":
